"""Educación Financiera EPJA Media N1 y N2, módulo 1 (parte 1): escasez y costo alternativo, endeudamiento y morosidad (OAD-01); necesidades, intercambio y consumo responsable (OAD-02); tipos de dinero y medios de pago (OAD-03); decisiones fundamentadas según costos y tipos de dinero (OAD-04). Todo en papel; cifras de ejemplo inventadas, sin tasas ni comisiones reales."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Boletas, cartolas, tarjetas y cheques de ejemplo escritos o dibujados en papel; no se usa dinero real, ni datos personales, ni calculadora ni internet. Todo se resuelve con lo escrito en la ficha. Las cifras son inventadas y no corresponden a tasas, comisiones ni precios reales."
build = make_build(MATERIALS)

O1 = "EPJA-EFIN-NM1y2-OAD-01"
O2 = "EPJA-EFIN-NM1y2-OAD-02"
O3 = "EPJA-EFIN-NM1y2-OAD-03"
O4 = "EPJA-EFIN-NM1y2-OAD-04"
PRIOR = ["Ya he decidido en qué usar dinero o tiempo en mi vida diaria.", "Conozco palabras como sueldo, boleta, cuota y cuenta."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_):
    op = list(op)
    if isinstance(op[4], str):
        op[4] = [e.strip() for e in op[4].split(";")]
    build(oa, n, F, use=use, prior=PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc, op=op, reinforce=rf, extend=ex_)


